T = 'seventeenth pass, 2026-11-14'
links, F = [], []
NOTE = 'Old-source items without a template field, preserved as printed; nothing is mapped to a field.'


def link(pid, f, ed, cov):
    links.append(dict(p=pid, f=f, cat='A', status='completed', fields_status=f'pp.1-2 read in full (all 2 pages; text layer) ({T})', coverage=f'assessed by reading (2026-11-14, seventeenth pass) for the whole document (2 pp., {ed}): {cov}',
                      identity='SHA-256 equal to the cited archive file; product name on the page', note='Byte duplicate of the cited source.'))


def row(pid, f, ed, old, reason=NOTE, path='open_questions', action='propose_note', outcome='in_old_source_not_captured', form='statements and values as printed (no template field)', page=1, new_text='(same file; byte duplicate in the new archive)', cmp='existing: not recorded', tier=1):
    F.append(dict(p=pid, tier=tier, path=path, old=old, new_f=f, new_p=page, new_text=new_text, unit='as printed', form=form, qual='as printed', method='as printed', cond='', basis='',
                  outcome=outcome, action=action, reason=reason, old_rev=f're-read manually: {f} ({ed}) pp.1-2 whole text ({T})', cmp_override=cmp))


